import { portProtocolsOverlap } from './serviceUtils'
import type { Host, Service, ServicePort } from './types'

export const UNASSIGNED_HOST_FILTER = 'unassigned'

export interface PortAssignment {
  id: string
  serviceId: string
  serviceName: string
  serviceStatus: Service['status']
  containerName: string
  dockerImage: string
  hostId?: string
  hostName: string
  hostPort?: number
  containerPort?: number
  protocol: ServicePort['protocol']
  conflict: boolean
  conflictingServiceNames: string[]
  incomplete: boolean
}

export interface PortHostGroup {
  id: string
  name: string
  assignments: PortAssignment[]
}

interface PortMapOptions {
  query?: string
  hostFilter?: string
}

export function derivePortMap(
  services: Service[],
  hosts: Host[],
  { query = '', hostFilter = 'all' }: PortMapOptions = {},
): PortHostGroup[] {
  const hostNames = new Map(hosts.map((host) => [host.id, host.name]))
  const assignments: PortAssignment[] = services.flatMap((service) =>
    service.ports.map((port, portIndex) => ({
      id: `${service.id}:${portIndex}`,
      serviceId: service.id,
      serviceName: service.name,
      serviceStatus: service.status,
      containerName: service.containerName,
      dockerImage: service.dockerImage,
      hostId: service.hostId,
      hostName: service.hostId ? (hostNames.get(service.hostId) ?? 'Unknown host') : 'Unassigned host',
      hostPort: port.hostPort,
      containerPort: port.containerPort,
      protocol: port.protocol,
      conflict: false,
      conflictingServiceNames: [],
      incomplete:
        !service.hostId ||
        port.hostPort === undefined ||
        port.containerPort === undefined ||
        port.protocol === 'unknown',
    })),
  )

  assignments.forEach((assignment, index) => {
    assignments.slice(index + 1).forEach((candidate) => {
      if (
        assignment.hostId &&
        assignment.hostId === candidate.hostId &&
        assignment.hostPort !== undefined &&
        assignment.hostPort === candidate.hostPort &&
        portProtocolsOverlap(assignment.protocol, candidate.protocol)
      ) {
        assignment.conflict = true
        candidate.conflict = true
        if (
          assignment.serviceId !== candidate.serviceId &&
          !assignment.conflictingServiceNames.includes(candidate.serviceName)
        ) {
          assignment.conflictingServiceNames.push(candidate.serviceName)
        }
        if (
          candidate.serviceId !== assignment.serviceId &&
          !candidate.conflictingServiceNames.includes(assignment.serviceName)
        ) {
          candidate.conflictingServiceNames.push(assignment.serviceName)
        }
      }
    })
  })

  const normalizedQuery = query.trim().toLowerCase()
  const visible = assignments.filter((assignment) => {
    const matchesHost =
      hostFilter === 'all' ||
      (hostFilter === UNASSIGNED_HOST_FILTER
        ? !assignment.hostId
        : assignment.hostId === hostFilter)
    const searchable = [
      assignment.serviceName,
      assignment.containerName,
      assignment.dockerImage,
      assignment.hostName,
      assignment.hostPort?.toString(),
      assignment.containerPort?.toString(),
      assignment.protocol,
    ]
      .filter(Boolean)
      .join(' ')
      .toLowerCase()
    return matchesHost && (!normalizedQuery || searchable.includes(normalizedQuery))
  })

  const groups = new Map<string, PortHostGroup>()
  visible.forEach((assignment) => {
    const id = assignment.hostId ?? UNASSIGNED_HOST_FILTER
    const group = groups.get(id) ?? { id, name: assignment.hostName, assignments: [] }
    group.assignments.push(assignment)
    groups.set(id, group)
  })

  return [...groups.values()]
    .map((group) => ({
      ...group,
      assignments: group.assignments.sort(
        (left, right) =>
          (left.hostPort ?? Number.POSITIVE_INFINITY) -
            (right.hostPort ?? Number.POSITIVE_INFINITY) ||
          left.serviceName.localeCompare(right.serviceName) ||
          left.id.localeCompare(right.id),
      ),
    }))
    .sort((left, right) => {
      if (left.id === UNASSIGNED_HOST_FILTER) return 1
      if (right.id === UNASSIGNED_HOST_FILTER) return -1
      return left.name.localeCompare(right.name)
    })
}

import { describe, expect, it } from 'vitest'
import { derivePortMap, UNASSIGNED_HOST_FILTER } from './portMap'
import { createService } from './serviceUtils'
import type { Host, Service, ServicePort } from './types'

const timestamp = '2026-08-02T12:00:00.000Z'
const hosts: Host[] = [
  { id: 'alpha', name: 'Alpha host', type: 'nas', ipAddress: '', operatingSystem: '', notes: '', createdAt: timestamp, updatedAt: timestamp },
  { id: 'beta', name: 'Beta host', type: 'nas', ipAddress: '', operatingSystem: '', notes: '', createdAt: timestamp, updatedAt: timestamp },
]

function service(id: string, hostId: string | undefined, ports: ServicePort[], details: Partial<Service> = {}): Service {
  return { ...createService(id), id, name: id, hostId, ports, ...details }
}

describe('derived Port Map', () => {
  it('groups by host, keeps multiple mappings, and places unassigned services last', () => {
    const groups = derivePortMap([
      service('Multi', 'alpha', [
        { hostPort: 9000, containerPort: 90, protocol: 'tcp', description: '' },
        { hostPort: 8000, containerPort: 80, protocol: 'tcp', description: '' },
      ]),
      service('Loose', undefined, [{ hostPort: 7000, protocol: 'udp', description: '' }]),
    ], hosts)

    expect(groups.map((group) => group.name)).toEqual(['Alpha host', 'Unassigned host'])
    expect(groups[0].assignments.map((assignment) => assignment.hostPort)).toEqual([8000, 9000])
    expect(groups[1].id).toBe(UNASSIGNED_HOST_FILTER)
  })

  it('sorts valid host ports numerically, incomplete ports last, then by service name', () => {
    const assignments = derivePortMap([
      service('Zulu', 'alpha', [{ containerPort: 1, protocol: 'tcp', description: '' }]),
      service('Beta', 'alpha', [{ hostPort: 100, protocol: 'tcp', description: '' }]),
      service('Alpha', 'alpha', [{ hostPort: 100, containerPort: 2, protocol: 'tcp', description: '' }]),
      service('Charlie', 'alpha', [{ hostPort: 20, containerPort: 3, protocol: 'tcp', description: '' }]),
    ], hosts)[0].assignments
    expect(assignments.map((assignment) => assignment.serviceName)).toEqual(['Charlie', 'Alpha', 'Beta', 'Zulu'])
  })

  it('records same-host conflict relationships using current protocol semantics', () => {
    const assignments = derivePortMap([
      service('TCP', 'alpha', [{ hostPort: 80, protocol: 'tcp', description: '' }]),
      service('Both', 'alpha', [{ hostPort: 80, protocol: 'both', description: '' }]),
      service('UDP', 'alpha', [{ hostPort: 81, protocol: 'udp', description: '' }]),
      service('Unknown one', 'alpha', [{ hostPort: 82, protocol: 'unknown', description: '' }]),
      service('Unknown two', 'alpha', [{ hostPort: 82, protocol: 'unknown', description: '' }]),
      service('Other host', 'beta', [{ hostPort: 80, protocol: 'tcp', description: '' }]),
    ], hosts).flatMap((group) => group.assignments)

    expect(assignments.find((item) => item.serviceName === 'TCP')).toMatchObject({ conflict: true, conflictingServiceNames: ['Both'] })
    expect(assignments.find((item) => item.serviceName === 'UDP')?.conflict).toBe(false)
    expect(assignments.find((item) => item.serviceName === 'Unknown one')?.conflict).toBe(true)
    expect(assignments.find((item) => item.serviceName === 'Other host')?.conflict).toBe(false)
  })

  it('keeps same-service conflicts while listing each different service only once', () => {
    const assignments = derivePortMap([
      service('Primary', 'alpha', [
        { hostPort: 8080, protocol: 'tcp', description: '' },
        { hostPort: 8080, protocol: 'both', description: '' },
      ]),
      service('Other', 'alpha', [
        { hostPort: 8080, protocol: 'tcp', description: '' },
        { hostPort: 8080, protocol: 'both', description: '' },
      ]),
    ], hosts)[0].assignments

    const primaryAssignments = assignments.filter((assignment) => assignment.serviceName === 'Primary')
    expect(primaryAssignments.every((assignment) => assignment.conflict)).toBe(true)
    expect(primaryAssignments.map((assignment) => assignment.conflictingServiceNames)).toEqual([
      ['Other'],
      ['Other'],
    ])
    expect(assignments.find((assignment) => assignment.serviceName === 'Other')?.conflictingServiceNames).toEqual(['Primary'])
  })

  it.each([
    ['service name', 'media', 'Media'],
    ['host name', 'alpha host', 'Media'],
    ['host port', '8080', 'Media'],
    ['container port', '3000', 'Media'],
    ['protocol', 'tcp', 'Media'],
    ['container name', 'media-app', 'Media'],
    ['Docker image', 'example/media', 'Media'],
  ])('searches by %s', (_field, query, expected) => {
    const result = derivePortMap([
      service('Media', 'alpha', [{ hostPort: 8080, containerPort: 3000, protocol: 'tcp', description: '' }], {
        containerName: 'media-app', dockerImage: 'example/media:1',
      }),
      service('Other', 'beta', [{ hostPort: 9000, containerPort: 9000, protocol: 'udp', description: '' }]),
    ], hosts, { query })
    expect(result.flatMap((group) => group.assignments).map((item) => item.serviceName)).toEqual([expected])
  })

  it('filters assigned and unassigned host groups', () => {
    const services = [
      service('Assigned', 'alpha', [{ hostPort: 1, protocol: 'tcp', description: '' }]),
      service('Loose', undefined, [{ hostPort: 2, protocol: 'tcp', description: '' }]),
    ]
    expect(derivePortMap(services, hosts, { hostFilter: 'alpha' }).map((group) => group.name)).toEqual(['Alpha host'])
    expect(derivePortMap(services, hosts, { hostFilter: UNASSIGNED_HOST_FILTER }).map((group) => group.name)).toEqual(['Unassigned host'])
  })
})

import { derivePortMap, UNASSIGNED_HOST_FILTER } from '../domain/portMap'
import type { Host, Service } from '../domain/types'

interface PortMapViewProps {
  services: Service[]
  hosts: Host[]
  query: string
  hostFilter: string
  onQueryChange: (query: string) => void
  onHostFilterChange: (hostId: string) => void
  onEditService: (service: Service) => void
}

export function PortMapView({
  services,
  hosts,
  query,
  hostFilter,
  onQueryChange,
  onHostFilterChange,
  onEditService,
}: PortMapViewProps) {
  const groups = derivePortMap(services, hosts, { query, hostFilter })
  const portCount = services.reduce((count, service) => count + service.ports.length, 0)
  const assignmentCount = groups.reduce((count, group) => count + group.assignments.length, 0)
  const conflictCount = groups.reduce(
    (count, group) => count + group.assignments.filter((assignment) => assignment.conflict).length,
    0,
  )

  let emptyTitle = 'No port assignments match'
  let emptyMessage = 'Clear the search or choose another host.'
  if (services.length === 0) {
    emptyTitle = 'No services yet'
    emptyMessage = 'Add a service before mapping ports.'
  } else if (portCount === 0) {
    emptyTitle = 'No port mappings yet'
    emptyMessage = 'Edit a service to record its first port mapping.'
  } else if (!query.trim() && hostFilter !== 'all') {
    emptyTitle = 'No ports for this host'
    emptyMessage = 'Choose another host or edit a service assignment.'
  }

  return (
    <section className="workspace port-map" aria-labelledby="port-map-title">
      <div className="section-heading">
        <div>
          <p className="eyebrow">Assignment overview</p>
          <h2 id="port-map-title">Port Map</h2>
        </div>
        <p className={conflictCount ? 'port-map-count has-conflicts' : 'port-map-count'}>
          {assignmentCount} visible assignments · {conflictCount} conflicting assignments
        </p>
      </div>

      <div className="port-map-controls">
        <label className="search-field">
          <span>Search Port Map</span>
          <input
            type="search"
            value={query}
            onChange={(event) => onQueryChange(event.target.value)}
            placeholder="Search services, hosts, ports, protocols…"
          />
        </label>
        <label>
          <span>Filter Port Map by host</span>
          <select value={hostFilter} onChange={(event) => onHostFilterChange(event.target.value)}>
            <option value="all">All hosts</option>
            {hosts.map((host) => (
              <option key={host.id} value={host.id}>{host.name}</option>
            ))}
            <option value={UNASSIGNED_HOST_FILTER}>Unassigned host</option>
          </select>
        </label>
      </div>

      {groups.length === 0 ? (
        <div className="empty-state compact">
          <h3>{emptyTitle}</h3>
          <p>{emptyMessage}</p>
        </div>
      ) : (
        <div className="port-host-groups">
          {groups.map((group) => (
            <section className="port-host-group" key={group.id} aria-labelledby={`port-host-${group.id}`}>
              <div className="port-host-heading">
                <h3 id={`port-host-${group.id}`}>{group.name}</h3>
                <span>{group.assignments.length} {group.assignments.length === 1 ? 'assignment' : 'assignments'}</span>
              </div>
              <div className="port-table" role="table" aria-label={`${group.name} port assignments`}>
                <div className="port-table-header" role="row">
                  <span role="columnheader">Host port</span><span role="columnheader">Container port</span>
                  <span role="columnheader">Protocol</span><span role="columnheader">Service</span>
                  <span role="columnheader">Host</span><span role="columnheader">Status</span><span role="columnheader">Actions</span>
                </div>
                {group.assignments.map((assignment) => (
                  <div
                    className={`port-assignment${assignment.conflict ? ' port-conflict' : ''}${assignment.incomplete ? ' port-incomplete' : ''}`}
                    role="row"
                    aria-label={`${assignment.serviceName}, host port ${assignment.hostPort ?? 'missing'}, container port ${assignment.containerPort ?? 'missing'}, ${assignment.protocol}`}
                    key={assignment.id}
                  >
                    <span role="cell" data-label="Host port">{assignment.hostPort ?? 'Missing'}</span>
                    <span role="cell" data-label="Container port">{assignment.containerPort ?? 'Missing'}</span>
                    <span role="cell" data-label="Protocol">{assignment.protocol}</span>
                    <span role="cell" data-label="Service"><strong>{assignment.serviceName}</strong></span>
                    <span role="cell" data-label="Host">{assignment.hostName}</span>
                    <span role="cell" data-label="Status"><span className={`status-badge status-${assignment.serviceStatus}`}>{assignment.serviceStatus}</span></span>
                    <span role="cell" data-label="Actions">
                      <button className="text-button" type="button" onClick={() => onEditService(services.find((service) => service.id === assignment.serviceId)!)} aria-label={`Edit service ${assignment.serviceName}`}>Edit service</button>
                    </span>
                    {(assignment.conflict || assignment.incomplete) && (
                      <span className="port-assignment-notes" role="cell" data-label="Issues">
                        {assignment.conflict && (
                          <span className="conflict-detail" role="status">
                            Conflict: {assignment.hostPort}/{assignment.protocol} on {assignment.hostName}
                            {assignment.conflictingServiceNames.length > 0 && `; also used by ${assignment.conflictingServiceNames.join(', ')}`}.
                          </span>
                        )}
                        {assignment.hostPort === undefined && <span>Host port is missing.</span>}
                        {assignment.containerPort === undefined && <span>Container port is missing.</span>}
                        {assignment.protocol === 'unknown' && <span>Protocol is unknown.</span>}
                        {!assignment.hostId && <span>Service has no assigned host.</span>}
                      </span>
                    )}
                  </div>
                ))}
              </div>
            </section>
          ))}
        </div>
      )}
    </section>
  )
}

